async function prepareShell() {
  const entries = await Promise.all(APP_SHELL.map(async (path) => {
    const response = await fetch(new Request(new URL(path, self.registration.scope), { cache: "reload", signal: AbortSignal.timeout(10000) }));
    if (!response.ok || response.redirected) throw new Error("App update unavailable");
    const bytes = await response.clone().arrayBuffer();
    const digest = await crypto.subtle.digest("SHA-256", bytes);
    const hash = [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
    if (hash !== SHELL_INTEGRITY[path]) throw new Error("Incomplete app update");
    return [path, response];
  }));
  const cache = await caches.open(CACHE_NAME);
  await Promise.all(entries.map(([path, response]) => cache.put(path, response)));
}

